     1→// apps/desktop/src/components/global-tab-bar/index.tsx
     2→
     3→/**
     4→ * Global Tab Bar Component
     5→ *
     6→ * Browser-like tab bar for the desktop app:
     7→ * - Navigation buttons (back/forward)
     8→ * - Tab items (pinned and regular) with drag-and-drop reordering
     9→ * - Window controls (Windows only)
    10→ * - macOS traffic light space accommodation
    11→ */
    12→
    13→import { useState, useEffect, useCallback, useRef } from "react";
    14→import { useTranslation } from "react-i18next";
    15→import { ChevronLeft, ChevronRight, Plus } from "lucide-react";
    16→import { toast } from "@/hooks/use-toast";
    17→import {
    18→  DndContext,
    19→  closestCenter,
    20→  KeyboardSensor,
    21→  PointerSensor,
    22→  useSensor,
    23→  useSensors,
    24→  type DragEndEvent,
    25→  type DragStartEvent,
    26→} from "@dnd-kit/core";
    27→import {
    28→  SortableContext,
    29→  sortableKeyboardCoordinates,
    30→  horizontalListSortingStrategy,
    31→} from "@dnd-kit/sortable";
    32→import { Button } from "@/components/ui/button";
    33→import {
    34→  ContextMenu,
    35→  ContextMenuContent,
    36→  ContextMenuItem,
    37→  ContextMenuLabel,
    38→  ContextMenuSeparator,
    39→  ContextMenuTrigger,
    40→} from "@/components/ui/context-menu";
    41→import {
    42→  Tooltip,
    43→  TooltipContent,
    44→  TooltipProvider,
    45→  TooltipTrigger,
    46→} from "@/components/ui/tooltip";
    47→import { cn } from "@/lib/utils";
    48→import { useTabList, useActiveTabState, useTabActions, useTabNavigation } from "@/hooks/use-page-tabs";
    49→import { useTabStore } from "@/stores/tab-store";
    50→import { SortableTabItem } from "./sortable-tab-item";
    51→import { WindowControls } from "./window-controls";
    52→import { createTabNavigationState } from "@/navigation/tab-navigation";
    53→import { buildColdStartBreadcrumb } from "@/navigation/navigate";
    54→
    55→export interface GlobalTabBarProps {
    56→  className?: string;
    57→}
    58→
    59→export function GlobalTabBar({ className }: GlobalTabBarProps) {
    60→  const { t } = useTranslation();
    61→  const [isMacOS, setIsMacOS] = useState(false);
    62→  const [shouldReserveMacOSControlsSpace, setShouldReserveMacOSControlsSpace] = useState(false);
    63→  const [activeId, setActiveId] = useState<string | null>(null);
    64→  const [newTabIds, setNewTabIds] = useState<Set<string>>(new Set());
    65→  const prevTabIdsRef = useRef<string[]>([]);
    66→
    67→  // Detect platform for macOS traffic light spacing
    68→  useEffect(() => {
    69→    let mounted = true;
    70→    let unlisten: (() => void) | null = null;
    71→
    72→    const detectPlatform = async () => {
    73→      try {
    74→        const [{ platform }, { getCurrentWindow }] = await Promise.all([
    75→          import("@tauri-apps/plugin-os"),
    76→          import("@tauri-apps/api/window"),
    77→        ]);
    78→
    79→        if (!mounted) return;
    80→
    81→        const isMac = platform() === "macos";
    82→        setIsMacOS(isMac);
    83→
    84→        const appWindow = getCurrentWindow();
    85→
    86→        if (!isMac) {
    87→          setShouldReserveMacOSControlsSpace(false);
    88→          return;
    89→        }
    90→
    91→        const updateWindowState = async () => {
    92→          const isFullscreen = await appWindow.isFullscreen();
    93→
    94→          if (mounted) {
    95→            // Keep leading space while macOS traffic lights remain visible.
    96→            // Only reclaim the space in native fullscreen, where the controls
    97→            // are no longer occupying the leading edge of the title bar.
    98→            setShouldReserveMacOSControlsSpace(!isFullscreen);
    99→          }
   100→        };
   101→
   102→        await updateWindowState();
   103→        unlisten = await appWindow.onResized(() => {
   104→          void updateWindowState();
   105→        });
   106→      } catch {
   107→        // In web dev mode, default to non-macOS
   108→        setIsMacOS(false);
   109→        setShouldReserveMacOSControlsSpace(false);
   110→      }
   111→    };
   112→    detectPlatform();
   113→
   114→    return () => {
   115→      mounted = false;
   116→      if (unlisten) {
   117→        unlisten();
   118→      }
   119→    };
   120→  }, []);
   121→
   122→  // Get tab data from granular hooks
   123→  const tabs = useTabList();
   124→  const { activeTabId, canGoBack, canGoForward } = useActiveTabState();
   125→  const { switchToTab, closeTab, detachTabToNewWindow, getTabLink } = useTabActions();
   126→  const { goBackInTab, goForwardInTab, jumpToHistory } = useTabNavigation();
   127→
   128→  // Get additional store actions
   129→  const pinTab = useTabStore((state) => state.pinTab);
   130→  const unpinTab = useTabStore((state) => state.unpinTab);
   131→  const closeOtherTabs = useTabStore((state) => state.closeOtherTabs);
   132→  const closeTabsToRight = useTabStore((state) => state.closeTabsToRight);
   133→  const duplicateTab = useTabStore((state) => state.duplicateTab);
   134→  const reopenClosedTab = useTabStore((state) => state.reopenClosedTab);
   135→  const closeAllTabs = useTabStore((state) => state.closeAllTabs);
   136→  const moveTab = useTabStore((state) => state.moveTab);
   137→  const hasRecentlyClosedTabs = useTabStore((state) => state.recentlyClosedTabs.length > 0);
   138→
   139→  // Track newly added tabs for entrance animation
   140→  useEffect(() => {
   141→    const currentTabIds = tabs.map((t) => t.id);
   142→    const prevTabIds = prevTabIdsRef.current;
   143→
   144→    // Find new tabs (ids that exist now but didn't exist before)
   145→    const addedIds = currentTabIds.filter((id) => !prevTabIds.includes(id));
   146→
   147→    // Always update ref to prevent re-detecting the same tabs
   148→    prevTabIdsRef.current = currentTabIds;
   149→
   150→    if (addedIds.length > 0) {
   151→      setNewTabIds((prev) => {
   152→        const next = new Set(prev);
   153→        addedIds.forEach((id) => next.add(id));
   154→        return next;
   155→      });
   156→
   157→      // Remove from new tabs after animation completes
   158→      const timer = setTimeout(() => {
   159→        setNewTabIds((prev) => {
   160→          const next = new Set(prev);
   161→          addedIds.forEach((id) => next.delete(id));
   162→          return next;
   163→        });
   164→      }, 350);
   165→
   166→      return () => clearTimeout(timer);
   167→    }
   168→  }, [tabs]);
   169→
   170→  // DnD sensors
   171→  const sensors = useSensors(
   172→    useSensor(PointerSensor, {
   173→      activationConstraint: {
   174→        distance: 5, // 5px movement before drag starts
   175→      },
   176→    }),
   177→    useSensor(KeyboardSensor, {
   178→      coordinateGetter: sortableKeyboardCoordinates,
   179→    })
   180→  );
   181→
   182→  // DnD handlers
   183→  const handleDragStart = useCallback((event: DragStartEvent) => {
   184→    setActiveId(event.active.id as string);
   185→  }, []);
   186→
   187→  const handleDragEnd = useCallback(
   188→    (event: DragEndEvent) => {
   189→      const { active, over } = event;
   190→      setActiveId(null);
   191→
   192→      if (over && active.id !== over.id) {
   193→        const oldIndex = tabs.findIndex((t) => t.id === active.id);
   194→        const newIndex = tabs.findIndex((t) => t.id === over.id);
   195→        if (oldIndex !== -1 && newIndex !== -1) {
   196→          moveTab(oldIndex, newIndex);
   197→        }
   198→      }
   199→    },
   200→    [tabs, moveTab]
   201→  );
   202→
   203→  // Handlers for tab actions
   204→  const handlePinTab = useCallback(
   205→    (tabId: string) => {
   206→      pinTab(tabId);
   207→    },
   208→    [pinTab]
   209→  );
   210→
   211→  const handleUnpinTab = useCallback(
   212→    (tabId: string) => {
   213→      unpinTab(tabId);
   214→    },
   215→    [unpinTab]
   216→  );
   217→
   218→  const handleCloseOthers = useCallback(
   219→    (tabId: string) => {
   220→      closeOtherTabs(tabId);
   221→    },
   222→    [closeOtherTabs]
   223→  );
   224→
   225→  const handleCloseRight = useCallback(
   226→    (tabId: string) => {
   227→      closeTabsToRight(tabId);
   228→    },
   229→    [closeTabsToRight]
   230→  );
   231→
   232→  const handleDuplicateTab = useCallback(
   233→    (tabId: string) => {
   234→      duplicateTab(tabId);
   235→    },
   236→    [duplicateTab]
   237→  );
   238→
   239→  const handleMoveTabToStart = useCallback(
   240→    (tabId: string) => {
   241→      const fromIndex = tabs.findIndex((tab) => tab.id === tabId);
   242→      if (fromIndex <= 0) return;
   243→      moveTab(fromIndex, 0);
   244→    },
   245→    [moveTab, tabs]
   246→  );
   247→
   248→  const handleMoveTabToEnd = useCallback(
   249→    (tabId: string) => {
   250→      const fromIndex = tabs.findIndex((tab) => tab.id === tabId);
   251→      if (fromIndex === -1 || fromIndex >= tabs.length - 1) return;
   252→      moveTab(fromIndex, tabs.length - 1);
   253→    },
   254→    [moveTab, tabs]
   255→  );
   256→
   257→  const handleReopenClosedTab = useCallback(() => {
   258→    reopenClosedTab();
   259→  }, [reopenClosedTab]);
   260→
   261→  const handleCloseAllTabs = useCallback(() => {
   262→    closeAllTabs();
   263→  }, [closeAllTabs]);
   264→
   265→  const handleCopyTabLink = useCallback(
   266→    async (tabId: string) => {
   267→      const link = getTabLink(tabId);
   268→      if (!link) return;
   269→
   270→      try {
   271→        await navigator.clipboard.writeText(link);
   272→        toast.success(t("pageSection.linkCopied", "Link copied to clipboard"));
   273→      } catch (error) {
   274→        console.error("Failed to copy tab link:", error);
   275→        toast.error(t("common.copyFailed", "Failed to copy"));
   276→      }
   277→    },
   278→    [getTabLink, t]
   279→  );
   280→
   281→  const handleDetachTab = useCallback(
   282→    async (tabId: string) => {
   283→      try {
   284→        const detached = await detachTabToNewWindow(tabId);
   285→        if (!detached) {
   286→          toast.error(t("tabBar.detachUnavailable", "This tab cannot be detached"));
   287→        }
   288→      } catch (error) {
   289→        console.error("Failed to detach tab:", error);
   290→        toast.error(t("common.error"));
   291→      }
   292→    },
   293→    [detachTabToNewWindow, t]
   294→  );
   295→
   296→  const activeTab = tabs.find((tab) => tab.id === activeTabId) ?? null;
   297→  const backHistoryItems = activeTab
   298→    ? activeTab.navigationHistory
   299→        .slice(0, activeTab.historyIndex)
   300→        .map((state, index) => ({
   301→          historyIndex: index,
   302→          label:
   303→            state.breadcrumbStack[state.breadcrumbStack.length - 1]?.label ??
   304→            state.url,
   305→        }))
   306→        .reverse()
   307→    : [];
   308→  const forwardHistoryItems = activeTab
   309→    ? activeTab.navigationHistory
   310→        .slice(activeTab.historyIndex + 1)
   311→        .map((state, offset) => ({
   312→          historyIndex: activeTab.historyIndex + offset + 1,
   313→          label:
   314→            state.breadcrumbStack[state.breadcrumbStack.length - 1]?.label ??
   315→            state.url,
   316→        }))
   317→    : [];
   318→
   319→  // Get openTab action for creating new tabs
   320→  const openTab = useTabStore((state) => state.openTab);
   321→
   322→  // Handle new tab creation
   323→  const handleNewTab = useCallback(() => {
   324→    const url = "/workspace";
   325→    openTab({
   326→      navigationState: createTabNavigationState(url, buildColdStartBreadcrumb(url)),
   327→      pinned: false,
   328→    });
   329→  }, [openTab]);
   330→
   331→
   332→  // Tab IDs for sortable context
   333→  const tabIds = tabs.map((t) => t.id);
   334→
   335→  return (
   336→    <TooltipProvider delayDuration={300}>
   337→      <div
   338→        data-tauri-drag-region
   339→        className={cn(
   340→          "flex items-center border-b bg-muted/30",
   341→          isMacOS ? "h-8" : "h-10",
   342→          className
   343→        )}
   344→      >
   345→        {/* Left side: macOS traffic light space + Navigation buttons */}
   346→        <div
   347→          data-tauri-drag-region
   348→          className={cn(
   349→            "flex items-center gap-1 px-2 shrink-0",
   350→            shouldReserveMacOSControlsSpace && "pl-20"
   351→          )}
   352→        >
   353→          {/* Back button */}
   354→          <ContextMenu>
   355→            <Tooltip>
   356→              <TooltipTrigger asChild>
   357→                <ContextMenuTrigger asChild>
   358→                  <Button
   359→                    variant="ghost"
   360→                    size="icon"
   361→                    className={cn(isMacOS ? "h-6 w-6" : "h-7 w-7")}
   362→                    onClick={goBackInTab}
   363→                    disabled={!canGoBack}
   364→                  >
   365→                    <ChevronLeft className={cn(isMacOS ? "h-3.5 w-3.5" : "h-4 w-4")} />
   366→                  </Button>
   367→                </ContextMenuTrigger>
   368→              </TooltipTrigger>
   369→              <TooltipContent side="bottom" className="text-xs">
   370→                {t("common.back", "Go Back")}
   371→              </TooltipContent>
   372→            </Tooltip>
   373→            <ContextMenuContent className="w-56">
   374→              <ContextMenuLabel>{t("tabBar.backHistory", "Back History")}</ContextMenuLabel>
   375→              {backHistoryItems.length > 0 ? (
   376→                backHistoryItems.map((item) => (
   377→                  <ContextMenuItem
   378→                    key={`back-${item.historyIndex}`}
   379→                    onClick={() => jumpToHistory(item.historyIndex)}
   380→                  >
   381→                    {item.label}
   382→                  </ContextMenuItem>
   383→                ))
   384→              ) : (
   385→                <ContextMenuItem disabled>
   386→                  {t("tabBar.noBackHistory", "No back history")}
   387→                </ContextMenuItem>
   388→              )}
   389→            </ContextMenuContent>
   390→          </ContextMenu>
   391→
   392→          {/* Forward button */}
   393→          <ContextMenu>
   394→            <Tooltip>
   395→              <TooltipTrigger asChild>
   396→                <ContextMenuTrigger asChild>
   397→                  <Button
   398→                    variant="ghost"
   399→                    size="icon"
   400→                    className={cn(isMacOS ? "h-6 w-6" : "h-7 w-7")}
   401→                    onClick={goForwardInTab}
   402→                    disabled={!canGoForward}
   403→                  >
   404→                    <ChevronRight className={cn(isMacOS ? "h-3.5 w-3.5" : "h-4 w-4")} />
   405→                  </Button>
   406→                </ContextMenuTrigger>
   407→              </TooltipTrigger>
   408→              <TooltipContent side="bottom" className="text-xs">
   409→                {t("common.forward", "Go Forward")}
   410→              </TooltipContent>
   411→            </Tooltip>
   412→            <ContextMenuContent className="w-56">
   413→              <ContextMenuLabel>{t("tabBar.forwardHistory", "Forward History")}</ContextMenuLabel>
   414→              {forwardHistoryItems.length > 0 ? (
   415→                forwardHistoryItems.map((item) => (
   416→                  <ContextMenuItem
   417→                    key={`forward-${item.historyIndex}`}
   418→                    onClick={() => jumpToHistory(item.historyIndex)}
   419→                  >
   420→                    {item.label}
   421→                  </ContextMenuItem>
   422→                ))
   423→              ) : (
   424→                <ContextMenuItem disabled>
   425→                  {t("tabBar.noForwardHistory", "No forward history")}
   426→                </ContextMenuItem>
   427→              )}
   428→            </ContextMenuContent>
   429→          </ContextMenu>
   430→        </div>
   431→
   432→        {/* Separator between nav and tabs */}
   433→        {tabs.length > 0 && (
   434→          <div className="h-5 w-px bg-border/50 mx-1 shrink-0" />
   435→        )}
   436→
   437→        {/* Tabs with drag-and-drop */}
   438→        <div className="flex items-center gap-1 px-1 overflow-x-auto scrollbar-none">
   439→          <DndContext
   440→            sensors={sensors}
   441→            collisionDetection={closestCenter}
   442→            onDragStart={handleDragStart}
   443→            onDragEnd={handleDragEnd}
   444→          >
   445→            <SortableContext items={tabIds} strategy={horizontalListSortingStrategy}>
   446→              {tabs.map((tab) => (
   447→                <SortableTabItem
   448→                  key={tab.id}
   449→                  tab={tab}
   450→                  isActive={tab.id === activeTabId}
   451→                  isOnlyTab={tabs.length === 1}
   452→                  isDragging={activeId === tab.id}
   453→                  isNew={newTabIds.has(tab.id)}
   454→                  onSelect={() => switchToTab(tab.id)}
   455→                  onClose={() => closeTab(tab.id)}
   456→                  onPin={() => handlePinTab(tab.id)}
   457→                  onUnpin={() => handleUnpinTab(tab.id)}
   458→                  onCloseOthers={() => handleCloseOthers(tab.id)}
   459→                  onCloseRight={() => handleCloseRight(tab.id)}
   460→                  onDuplicate={() => handleDuplicateTab(tab.id)}
   461→                  onReopenClosed={handleReopenClosedTab}
   462→                  onCopyLink={() => handleCopyTabLink(tab.id)}
   463→                  onDetach={() => handleDetachTab(tab.id)}
   464→                  onMoveToStart={() => handleMoveTabToStart(tab.id)}
   465→                  onMoveToEnd={() => handleMoveTabToEnd(tab.id)}
   466→                  canReopenClosed={hasRecentlyClosedTabs}
   467→                  canMoveToStart={tabs.findIndex((item) => item.id === tab.id) > 0}
   468→                  canMoveToEnd={tabs.findIndex((item) => item.id === tab.id) < tabs.length - 1}
   469→                />
   470→              ))}
   471→            </SortableContext>
   472→          </DndContext>
   473→
   474→          {/* New Tab button */}
   475→          <Tooltip>
   476→            <TooltipTrigger asChild>
   477→              <Button
   478→                variant="ghost"
   479→                size="icon"
   480→                className="h-7 w-7 shrink-0"
   481→                onClick={handleNewTab}
   482→              >
   483→                <Plus className="h-3.5 w-3.5" />
   484→              </Button>
   485→            </TooltipTrigger>
   486→            <TooltipContent side="bottom" className="text-xs">
   487→              {t("common.newTab", "New Tab")}
   488→            </TooltipContent>
   489→          </Tooltip>
   490→        </div>
   491→
   492→        {/* Spacer: drag region for window dragging + empty-space context menu */}
   493→        <ContextMenu>
   494→          <ContextMenuTrigger asChild>
   495→            <div
   496→              data-tauri-drag-region
   497→              className="flex-1 self-stretch"
   498→            />
   499→          </ContextMenuTrigger>
   500→          <ContextMenuContent className="w-52">
   501→            <ContextMenuItem onClick={handleNewTab}>
   502→              {t("common.newTab", "New Tab")}
   503→            </ContextMenuItem>
   504→            <ContextMenuItem onClick={handleReopenClosedTab} disabled={!hasRecentlyClosedTabs}>
   505→              {t("tabBar.reopenClosedTab", "Reopen Closed Tab")}
   506→            </ContextMenuItem>
   507→            <ContextMenuSeparator />
   508→            <ContextMenuItem onClick={handleCloseAllTabs} disabled={tabs.every((tab) => tab.pinned)}>
   509→              {t("tabBar.closeAllUnpinned", "Close All Unpinned Tabs")}
   510→            </ContextMenuItem>
   511→          </ContextMenuContent>
   512→        </ContextMenu>
   513→
   514→        {/* Right side: Window Controls only */}
   515→        <div className="flex items-center shrink-0">
   516→          <WindowControls />
   517→        </div>
   518→      </div>
   519→    </TooltipProvider>
   520→  );
   521→}
   522→
   523→// Re-export sub-components for flexibility
   524→export { SortableTabItem as TabItem } from "./sortable-tab-item";
   525→export { WindowControls } from "./window-controls";
