     1→/**
     2→ * IconDisplay Component
     3→ *
     4→ * Unified icon display component that supports:
     5→ * - Lucide icons (by name)
     6→ * - Emoji characters
     7→ * - Custom images (local path or URL)
     8→ */
     9→
    10→import { useState, useMemo, useEffect } from "react";
    11→import { FileText } from "lucide-react";
    12→import { cn } from "@/lib/utils";
    13→import { DynamicLucideIcon } from "./dynamic-lucide-icon";
    14→import { LUCIDE_ICON_MAP, DEFAULT_ICON_NAME } from "./constants";
    15→import { parseIconData, getIconSizeClass, getIconPixelSize } from "./utils";
    16→import type { IconData, IconSize } from "./types";
    17→
    18→export interface IconDisplayProps {
    19→  /** Icon data (new format) or string (old format) */
    20→  icon?: IconData | string | null;
    21→  /** Icon size preset or pixel value */
    22→  size?: IconSize | number;
    23→  /** Fallback icon when icon is empty or invalid */
    24→  fallback?: IconData | string;
    25→  /** Workspace path for resolving relative image paths */
    26→  workspacePath?: string;
    27→  /** Additional CSS classes */
    28→  className?: string;
    29→  /** Alt text for images */
    30→  alt?: string;
    31→}
    32→
    33→/**
    34→ * Internal component for rendering image icons
    35→ */
    36→function ImageIcon({
    37→  src,
    38→  size,
    39→  workspacePath,
    40→  className,
    41→  alt,
    42→}: {
    43→  src: string;
    44→  size: number;
    45→  workspacePath?: string;
    46→  className?: string;
    47→  alt?: string;
    48→}) {
    49→  const [error, setError] = useState(false);
    50→  const [loading, setLoading] = useState(true);
    51→
    52→  // Resolve the image URL
    53→  const imageUrl = useMemo(() => {
    54→    // Already a full URL or data URL
    55→    if (src.startsWith("http://") || src.startsWith("https://") || src.startsWith("data:")) {
    56→      return src;
    57→    }
    58→
    59→    // Relative path - need to construct URL through gateway
    60→    if (workspacePath) {
    61→      // Use gateway file serving endpoint
    62→      const gatewayUrl = import.meta.env.VITE_GATEWAY_URL || "http://127.0.0.1:18790";
    63→      return `${gatewayUrl}/api/file/read?workspace_path=${encodeURIComponent(workspacePath)}&file_path=${encodeURIComponent(src)}`;
    64→    }
    65→
    66→    // Fallback: treat as relative path (may not work without workspace)
    67→    return src;
    68→  }, [src, workspacePath]);
    69→
    70→  // Reset states when src changes
    71→  useEffect(() => {
    72→    setError(false);
    73→    setLoading(true);
    74→  }, [imageUrl]);
    75→
    76→  if (error) {
    77→    // Show fallback icon on error
    78→    return <FileText className={cn(getIconSizeClass(size), className)} />;
    79→  }
    80→
    81→  return (
    82→    <span
    83→      className={cn(
    84→        "inline-flex items-center justify-center overflow-hidden rounded",
    85→        className
    86→      )}
    87→      style={{ width: size, height: size }}
