   114→/**
   115→ * IconDisplay component
   116→ *
   117→ * Renders an icon based on its type (lucide, emoji, or image).
   118→ * Supports both new IconData format and legacy string format.
   119→ */
   120→export function IconDisplay({
   121→  icon,
   122→  size = "md",
   123→  fallback,
   124→  workspacePath,
   125→  className,
   126→  alt,
   127→}: IconDisplayProps) {
   128→  // Parse icon data from various formats
   129→  const iconData = useMemo(() => {
   130→    // Parse the main icon
   131→    let data: IconData | null = null;
   132→
   133→    if (icon) {
   134→      if (typeof icon === "string") {
   135→        data = parseIconData(icon);
   136→      } else {
   137→        data = icon;
   138→      }
   139→    }
   140→
   141→    // Use fallback if no valid icon
   142→    if (!data && fallback) {
   143→      if (typeof fallback === "string") {
   144→        data = parseIconData(fallback);
   145→      } else {
   146→        data = fallback;
   147→      }
   148→    }
   149→
   150→    // Ultimate fallback
   151→    if (!data) {
   152→      data = { type: "lucide", value: DEFAULT_ICON_NAME };
   153→    }
   154→
   155→    return data;
   156→  }, [icon, fallback]);
   157→
   158→  // Get size values
   159→  const sizeClass = getIconSizeClass(size);
   160→  const pixelSize = getIconPixelSize(size);
   161→
   162→  // Render based on icon type
   163→  switch (iconData.type) {
   164→    case "lucide": {
   165→      const StaticIcon = LUCIDE_ICON_MAP[iconData.value];
   166→      if (StaticIcon) {
   167→        return <StaticIcon className={cn(sizeClass, "shrink-0", className)} />;
   168→      }
   169→      // Fallback: dynamically load icons not in static map
   170→      return (
   171→        <DynamicLucideIcon
   172→          name={iconData.value}
   173→          size={pixelSize}
   174→          className={cn("shrink-0", className)}
   175→        />
   176→      );
   177→    }
   178→
   179→    case "emoji": {
   180→      // Calculate font size based on icon size (slightly smaller than container)
   181→      const fontSize = Math.floor(pixelSize * 0.85);
   182→      return (
   183→        <span
   184→          className={cn(
   185→            "inline-flex items-center justify-center shrink-0 leading-none",
   186→            className
   187→          )}
   188→          style={{
   189→            width: pixelSize,
   190→            height: pixelSize,
   191→            fontSize: `${fontSize}px`,
   192→          }}
   193→        >
   194→          {iconData.value}
   195→        </span>
   196→      );
   197→    }
   198→
   199→    case "image": {
   200→      return (
   201→        <ImageIcon
   202→          src={iconData.value}
   203→          size={pixelSize}
   204→          workspacePath={workspacePath}
   205→          className={className}
   206→          alt={alt}
   207→        />
   208→      );
   209→    }
   210→
   211→    default: {
   212→      // Fallback to default icon
   213→      return <FileText className={cn(sizeClass, "shrink-0", className)} />;
   214→    }
   215→  }
   216→}
   217→
   218→export default IconDisplay;
